    score -= next_slack / capacity * (0.31 + 0.52 * scarcity);
    score += residual_advantage;
    score += empty as f64 * (0.97 + 0.68 * progress);
    score += open_bins_count as f64 * 0.0014;
    score -= post_utilization * 0.135;
    score += granularity_bonus;

    // dead space ratio shaping: mid-utilization bins are the worst for future packing
    score -= dead_ratio * (0.42 + 0.66 * scarcity + 0.30 * (1.0 - progress));

    if fitting_bins_count == 1 {
        score -= 0.54 + 0.31 * (1.0 - progress);
    }

    if next_item_size > 0 && post >= next_item_size {
        score -= 0.31 + 0.37 * (1.0 - progress);
    }

    if empty == 1 && fitting_bins_count > 1 {
        let usable_slack = residual_fraction * capacity;
        if usable_slack >= item * 1.35 {
            score += 0.32 + 0.18 * progress;
        }
    }

    // lookahead balance: if the current item leaves room for the next item plus a bit more,
    // prefer that bin slightly (keeps the pair together without stranding)
    if next > 0.0 && post >= next {
        let pair_slack = (post - next) / capacity;
        score -= pair_slack * 0.22;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 + 1.0) / total_items as f64
    };

    let empty_bin = (bin_residual == bin_capacity) as i32;
    let residual_fraction = (residual / capacity).clamp(0.0, 1.0);
    let post_fraction = (post_residual as f64 / capacity).clamp(0.0, 1.0);
    let utilization = 1.0 - residual_fraction;
    let post_utilization = 1.0 - post_fraction;

    let next = next_item_size.max(1) as f64;
    let future_gap = (post_residual as f64 - next).max(0.0);
    let dead_space = if post_residual > 0 && post_residual < next {
        (next - post_residual as f64).powf(1.18)
    } else {
        0.0
    };

    // Prefer a tight fit, but account for the amount of usable space left.
    let exactness = if residual >= item {
        1.0 - ((residual - item) / capacity).min(1.0)
    } else {
        0.0
    };
    let usable_fit = if residual >= item {
        (residual - item + 1.0) / capacity
    } else {
        0.0
    };

    // A residual close to the mean is generally easier to consume consistently.
    let mean_gap = (mean_residual - residual).abs();
    let mean_affinity = 1.0 / (1.0 + mean_gap / capacity.max(1.0));

    // New bins are attractive only when existing bins are poorly fragmented.
    let new_bin = empty_bin as f64;
    let fragmentation = (mean_residual / capacity.max(1.0)).clamp(0.0, 1.0);
    let open_pressure = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).min(1.0)
    };

    let mut score = post_residual as f64 / 10.0;
    score -= exactness * (1.45 + 0.35 * progress);
    score -= usable_fit * (0.35 + 0.25 * open_pressure);
    score -= mean_affinity * (0.85 + 0.55 * (1.0 - progress));
    score += dead_space * (2.15 + 2.35 * (fitting_bins_count <= 1) as u8 as f64);
    score += future_gap * (0.055 + 0.035 * progress);

    // Small residuals are valuable: they can close a bin with little waste.
    if post_residual == 0 {
        score -= 1.35 + 0.55 * (1.0 - progress);
    } else if post_residual <= 2 && post_residual < next {
        score -= 0.22 * (next - post_residual as f64);
    }

    if fitting_bins_count == 1 {
        score -= 0.95 + 0.35 * (1.0 - progress);
    } else if fitting_bins_count <= 2 {
        score -= 0.18;
    }

    // Penalize an empty candidate relative to a genuinely good existing fit.
    score += new_bin * (1.65 + 1.35 * fragmentation + 0.45 * open_pressure);
    score += (open_bins_count as f64).sqrt() * 0.012;

    // Late in the stream, favor bins whose remaining gap is easier to fill.
    let late_weight = progress * progress;
    score += late_weight * (residual_fraction - post_fraction) * 0.42;
    score -= late_weight * post_utilization * 0.48;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let is_empty = (bin_residual == bin_capacity) as i32;

    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 + 1.0) / total_items as f64
    };

    let utilization = 1.0 - residual / capacity;
    let post_utilization = 1.0 - post / capacity;
    let residual_fraction = residual / capacity;
    let mean_gap = (mean_residual - residual).abs();
    let scarcity = if fitting_bins_count == 0 {
        1.0
    } else {
        1.0 / fitting_bins_count as f64
    };

    let next = next_item_size.max(1) as f64;
    let lookahead_size = next.min(item);
    let dead_space = if post > 0.0 && post < lookahead_size {
        lookahead_size - post
    } else {
        0.0
    };
    let dead_space_cost = dead_space * dead_space * (1.0 + 1.8 * scarcity);
    let residual_waste = if post == 0.0 {
        0.0
    } else {
        (post / capacity).powi(2) * (1.0 + 2.2 * progress)
    };

    let mut score = post;
    score += dead_space_cost * (1.9 + 1.4 * progress);
    score += residual_waste * (1.25 + 0.9 * scarcity);

    let fit_quality = if residual >= item {
        (residual - item + 1.0) / capacity
    } else {
        1.0 + (item - residual) / capacity
    };
    score -= fit_quality * (1.05 + 0.35 * scarcity);
    score -= utilization * (0.32 + 0.18 * progress);
    score += post_utilization * (0.22 + 0.28 * (1.0 - progress));

    let mean_preference = if mean_gap < 0.5 {
        1.0
    } else {
        1.0 / (1.0 + mean_gap)
    };
    score -= mean_preference * (0.52 + 0.55 * scarcity);

    let horizon = if next_item_size == 0 {
        progress * 0.25
    } else {
        (1.0 - progress) * (next_item_size as f64 / capacity)
    };
    score += residual_fraction * residual_fraction * (0.65 + 1.5 * horizon);

    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= 0.48 + 0.52 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - post).max(0.0) * 0.055;
    }

    if fitting_bins_count == 1 {
        score -= 0.68 + 0.32 * (1.0 - progress);
    }

    let new_bin_penalty = 0.72
        + 0.72 * progress
        + 0.18 * (open_bins_count as f64 / total_items.max(1) as f64).sqrt()
        - 0.22 * utilization;
    score += is_empty as f64 * new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let is_empty = (bin_residual == bin_capacity) as i32;
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 + 1.0) / total_items as f64
    };

