        1.0
    } else {
        (step_index as f64 + 1.0) / total_items as f64
    };

    let residual_fraction = (residual / capacity).clamp(0.0, 1.0);
    let post_fraction = (post / capacity).clamp(0.0, 1.0);
    let post_utilization = 1.0 - post_fraction;
    let immediate_slack = (residual - item).max(0.0);
    let slack_fraction = immediate_slack / capacity;
    let next_slack = if next > 0.0 {
        (post - next).max(0.0)
    } else {
        0.0
    };

    let mean_gap = (mean_residual - residual).abs() / capacity;
    let global_fit = 1.0 / (1.0 + mean_gap * 7.5);
    let concentration = residual_fraction * residual_fraction;
    let tightness = (1.0 - residual_fraction).powi(2);
    let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    let horizon = if next_item_size == 0 {
        progress * 0.35
    } else {
        (1.0 - progress) * (next / capacity)
    };

    let fit_quality = if residual >= item {
        1.0 - immediate_slack / capacity
    } else {
        1.0 + (item - residual) / capacity
    };

    let exact_fit = if immediate_slack <= 0.5 {
        1.0
    } else {
        (-immediate_slack / capacity * 18.0).exp()
    };

    let preserves_next = if next > 0.0 && post >= next {
        1.0
    } else {
        0.0
    };

    let next_dead_space = if next > 0.0 && post < next {
        (next - post) / capacity
    } else {
        0.0
    };

    let pair_fit = if next > 0.0 && post >= next {
        (next / capacity).min(1.0)
    } else {
        0.0
    };

    let residual_value = (mean_residual - residual) / capacity;
    let residual_advantage = residual_value * 0.34
        - residual_value * residual_value * 0.62;

    let fragmentation = if post > 0.0 && next > 0.0 && post < next {
        (next - post).powf(1.22) / capacity
    } else {
        0.0
    };

    let mut score = post * 0.115;
    score += fragmentation * (2.7 + 4.1 * scarcity);
    score += next_dead_space * (1.35 + 2.2 * scarcity);
    score += concentration * (0.78 + 2.35 * horizon);
    score += slack_fraction * (0.61 + 0.33 * (1.0 - progress));
    score -= global_fit * (0.72 + 1.18 * scarcity);
    score -= tightness * (0.77 + 1.47 * progress);
    score -= fit_quality * 0.93;
    score -= exact_fit * (0.29 + 0.31 * progress);
    score -= preserves_next * (0.39 + 0.53 * (1.0 - progress));
    score -= pair_fit * (0.26 + 0.48 * (1.0 - progress));
    score -= next_slack / capacity * (0.31 + 0.52 * scarcity);
    score += residual_advantage;
    score += empty as f64 * (0.97 + 0.68 * progress);
    score += open_bins_count as f64 * 0.0014;
    score -= post_utilization * 0.135;

    if fitting_bins_count == 1 {
        score -= 0.54 + 0.31 * (1.0 - progress);
    }

    if next_item_size > 0 && post >= next_item_size {
        score -= 0.31 + 0.37 * (1.0 - progress);
    }

    if empty == 1 && fitting_bins_count > 1 {
        let usable_slack = residual_fraction * capacity;
        if usable_slack >= item * 1.35 {
            score += 0.32 + 0.18 * progress;
        }
    }

    score
}

