    score -= relative_mean_gap * (0.72 + 1.1 * scarcity);
    score -= utilization * utilization * (0.68 + 1.35 * progress);
    score -= fit_excess * 1.08;
    score += overflow * 4.0;
    score += (mean_gap / capacity) * 0.34;
    score += is_empty as f64 * (0.92 + 0.78 * progress);

    score -= exact_next * (0.72 + 0.58 * (1.0 - progress));
    score -= reusable * (0.42 + 0.24 * progress);
    score += post_utilization * 0.22;

    if next > 0.0 {
        let next_shortfall = (next - post).max(0.0) / capacity;
        score += next_shortfall * (0.18 + 0.48 * scarcity);
        if post + 0.5 >= next {
            score -= 0.34 * (1.0 - progress);
        }
    }

    if fitting_bins_count == 1 {
        score -= 0.88 + 0.38 * (1.0 - progress);
    } else if fitting_bins_count > 1 {
        score -= 0.08 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    let pressure = if total_items == 0 {
        0.0
    } else {
        ((step_index + 1) as f64 / total_items as f64 - 0.5).abs() * 2.0
    };
    score += pressure * (post_fraction * 0.18 + is_empty as f64 * 0.12);
    score += open_bins_count as f64 * 0.0009;

    let residual_pressure = if fitting_bins_count > 0 {
        let fit_count = fitting_bins_count as f64;
        ((mean_residual - residual) / capacity).max(0.0) * (fit_count.min(8.0) / 8.0)
    } else {
        0.0
    };
    score -= residual_pressure * (0.46 + 0.22 * progress);

    let unusable_ratio = if smallest_known > 0.0 {
        (post / smallest_known).min(1.0)
    } else {
        0.0
    };
    let tiny_gap = if stranded {
        ((smallest_known - post) / capacity).min(1.0)
    } else {
        0.0
    };
    score += unusable_ratio * tiny_gap * (1.65 + 1.25 * scarcity);

    let future_fit = if next > 0.0 && post + 0.5 >= next {
        (post - next + 1.0) / capacity
    } else {
        0.0
    };
    score -= future_fit * (0.58 + 0.42 * (1.0 - progress));

    let residual_cube = residual_fraction * residual_fraction * residual_fraction;
    let post_cube = post_fraction * post_fraction * post_fraction;
    score -= residual_cube * (0.31 + 0.23 * progress);
    score += post_cube * (0.46 + 0.31 * scarcity);

    let gap_to_next = if next > 0.0 {
        (post - next).max(0.0) / capacity
    } else {
        0.0
    };
    let useful_holdover = if post >= next && next > 0.0 {
        ((post - next + 1.0) / capacity).min(1.0)
    } else {
        0.0
    };
    score -= useful_holdover * gap_to_next * (0.82 + 0.44 * (1.0 - progress));

    let near_dead = if post_fraction < 0.08 && post_fraction > 0.0 {
        (0.08 - post_fraction) / 0.08
    } else {
        0.0
    };
    score += near_dead * (0.74 + 1.36 * scarcity);

    let obsolete_gap = if post > 0.0 && post < item {
        let absolute = (item - post) / capacity;
        let normalized = absolute.min(0.5);
        let curvature = normalized * (1.0 - normalized * 1.45);
        curvature * (1.45 + 2.1 * scarcity)
    } else {
        0.0
    };
    score += obsolete_gap;

    let residual_floor = if residual_fraction < 0.10 && residual > 0.0 {
        let normalized = (0.10 - residual_fraction) / 0.10;
        normalized * normalized * (1.25 + 1.8 * scarcity)
    } else {
        0.0
    };
    score += residual_floor;

    let balanced_post = if post > 0.0 {
        let ideal = (item.min(next.max(item)) / capacity).clamp(0.05, 0.45);
        let distance = (post_fraction - ideal).abs();
        distance * distance * (0.68 + 0.42 * scarcity)
    } else {
        0.0
    };
    score += balanced_post;

    let near_exact = if post > 0.0 && next > 0.0 {
        let miss = (post - next).abs() / capacity;
        if miss < 0.025 {
            (0.025 - miss) / 0.025
        } else {
            0.0
        }
    } else {
        0.0
    };
    score -= near_exact * (0.72 + 0.28 * progress);

    let known_demand = if next > 0.0 { next } else { item };
    let residue_value = if post > 0.0 && post < known_demand {
        let gap = known_demand - post;
        let normalized_gap = (gap / capacity).min(1.0);
        let marginal = normalized_gap * (1.0 - 0.38 * post_fraction);
        let fit_severity = if fitting_bins_count <= 1 {
            1.0 + 0.38 * scarcity
        } else {
            0.82 + 0.08 * (fitting_bins_count as f64).min(4.0)
        };
        marginal * fit_severity * capacity * (0.72 + 0.34 * (1.0 - progress))
    } else {
        0.0
    };
    score += residue_value;

    let occupied_fraction = (post / capacity).clamp(0.0, 1.0);
    let empty_penalty = if is_empty == 1 {
        1.25 + 1.10 * progress + 0.35 * scarcity
    } else {
        0.0
    };
    score += empty_penalty;

    let competition = if fitting_bins_count > 0 {
        (fitting_bins_count as f64 - 1.0).min(7.0) / 7.0
    } else {
        1.0
    };
    let consolidation = competition
        * occupied_fraction
        * (1.0 - 0.62 * utilization)
        * (0.24 + 0.20 * (1.0 - progress));
    score -= consolidation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let empty_bin = (bin_residual == bin_capacity) as i32;
    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 + 1.0) / total_items as f64
    };

    let residual_fraction = (residual / capacity).clamp(0.0, 1.0);
    let post_fraction = (post / capacity).clamp(0.0, 1.0);
    let utilization = 1.0 - residual_fraction;
    let post_utilization = 1.0 - post_fraction;
    let next = next_item_size as f64;
    let expected_next = next.max(1.0);
    let mean_gap = (mean_residual - residual).abs();
    let mean_gap_ratio = mean_gap / capacity;

    // Exact-fit and near-fit bins are valuable, but avoid creating residual
    // pockets that are systematically smaller than the arriving item.
    let fit_band = if residual >= item {
        (residual - item) / capacity
    } else {
        1.0 + (item - residual) / capacity
    };
    let exact_fit = if residual == item { 1.0 } else { 0.0 };
    let next_exact = if next > 0.0 && post == next { 1.0 } else { 0.0 };
    let next_can_fit = if next > 0.0 && post >= next { 1.0 } else { 0.0 };

    // A candidate is less attractive when its unused space is close to the
    // global residual: this tends to reproduce many similar dead pockets.
    let concentration = residual_fraction * residual_fraction;
    let global_fit = 1.0 / (1.0 + mean_gap_ratio * 4.0);

    // Dead-space risk is nonlinear: a tiny unusable remainder is worse than
    // a larger one because it is less likely to be absorbed by future items.
    let next_gap = (expected_next - post).max(0.0);
    let dead_risk = if post > 0.0 && post < expected_next {
        (expected_next - post).powf(1.35) / capacity.max(1.0)
    } else {
        0.0
    };

    // New bins should be selected only when the best open-bin option has a
    // materially poor residual profile. The pressure grows late in a run,
    // but remains conservative when several bins can accept the item.
    let open_pressure = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    let late_pressure = progress * progress;
    let new_bin_penalty = if empty_bin != 0 {
        1.05
            + 0.95 * late_pressure
            + 0.45 * open_pressure
            - 0.35 * (open_bins_count as f64 / total_items.max(1) as f64).min(1.0)
    } else {
        0.0
    };

    let horizon_value = if next > 0.0 {
        (1.0 - progress) * (next / capacity)
    } else {
        progress * 0.30
    };

    let mut score = post_fraction * 1.45;
    score += concentration * (1.30 + 1.60 * horizon_value);
    score += dead_risk * (2.15 + 2.70 * open_pressure);
    score -= global_fit * (0.55 + 0.85 * open_pressure);
    score -= fit_band * 0.92;
    score -= exact_fit * 0.48;
    score += mean_gap_ratio * 0.30;
    score += new_bin_penalty;

    // Favor bins whose remainder is compatible with the known next item,
    // while not overvaluing them when many alternatives exist.
    score -= next_exact * (0.65 + 0.55 * (1.0 - progress));
    score -= next_can_fit * (0.32 + 0.42 * (1.0 - progress));
    score += next_gap / capacity.max(1.0) * (0.38 + 0.42 * progress);

    // Tightly filled bins are generally preferable, but this is softened for
    // empty bins and for late-run decisions where a new bin can be optimal.
    let tightness = utilization * utilization;
    score -= tightness * (0.72 + 1.25 * progress);
    score -= utilization * 0.18;
    score += post_utilization * 0.28;

    if fitting_bins_count == 1 {
        score -= 0.62 + 0.38 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let empty = (bin_residual == bin_capacity) as i32;

    let progress = if total_items == 0 {
        1.0
    } else {
        (step_index as f64 + 1.0) / total_items as f64
    };

    let residual_fraction = (residual / capacity).clamp(0.0, 1.0);
    let post_fraction = (post / capacity).clamp(0.0, 1.0);
    let utilization = 1.0 - residual_fraction;
    let post_utilization = 1.0 - post_fraction;

    // Prefer a residual that preserves useful, flexible capacity for future items.
    let slack = (residual - item).max(0.0);
    let next = next_item_size as f64;
    let future_fit = if next > 0.0 {
        (post >= next) as i32 as f64
    } else {
        0.5
    };

    // A new bin is competitive only when the best available placement is very poor.
    let fit_cost = if residual >= item {
        slack / capacity
    } else {
        1.0 + (item - residual) / capacity
    };
    let scarcity = if fitting_bins_count == 0 {
        1.0
    } else if fitting_bins_count == 1 {
        0.78
    } else {
        0.0
    };

    // Reward exact/compact placements, but avoid making the empty-bin alternative win
    // merely because all open bins have a little spare room.
    let compactness = if residual >= item {
        1.0 - (slack / capacity).min(1.0)
    } else {
        0.0
    };
    let mean_gap = (mean_residual - residual).abs();
    let mean_affinity = 1.0 / (1.0 + mean_gap / capacity.max(1.0));
    let concentration = residual_fraction * residual_fraction;
    let tightness = utilization * utilization;

    // Smaller residual is generally preferable, while preserving enough room for
    // the next observed item is valuable near the end of a stream.
    let mut score = 0.0;
    score += residual_fraction * (1.55 + 0.85 * progress);
    score += fit_cost * (0.55 + 0.45 * scarcity);
    score -= tightness * (0.48 + 0.38 * (1.0 - progress));
    score -= compactness * (0.42 + 0.30 * future_fit);
    score -= mean_affinity * (0.32 + 0.42 * scarcity);
    score += concentration * (0.42 + 0.38 * (1.0 - progress));

    // Dead space is penalized more strongly when it blocks the next item.
    let next_gap = if next > 0.0 {
        (next - post).max(0.0)
    } else {
        0.0
    };
    if next > 0.0 && post < next {
        score += next_gap * (0.10 + 0.18 * scarcity);
    } else if next > 0.0 {
        score -= 0.24 * (1.0 - progress);
    }

    // A new empty bin has no fragmentation cost, but must beat a reasonable fit.
    let empty_bias = 0.34 + 0.46 * scarcity + 0.16 * progress;
    score += empty as f64 * empty_bias;

    // Very small residuals are valuable: they are difficult to fill later.
    if residual <= item {
        score += (item - residual) / capacity * (0.60 + 0.35 * scarcity);
    }

    // Encourage closing out nearly full bins, especially late in the stream.
    score -= post_utilization * (0.30 + 0.28 * progress);
    score += open_bins_count as f64 * 0.0007;

    score
}
